<?php ac_hero('Timeline spine','Timeline Registry','Manage timeline-specific and GEN records with family grouping, status filters, and edit-shell drilldowns. docs/cue.txt remains draft until migrated and reviewed.'); $families=['PRE','OPEN','SET','SONG','TRN','CST','VID','LGT','FOG','STR','SPK','FIN','ENC','POST','GEN','DRAFT']; ?><section class="panel"><h2>Timeline Moment ID family reference</h2><div class="family-strip"><?php foreach($families as $f) echo ac_pill($f,'timeline'); ?></div></section><?php ac_filters(); foreach($families as $fam): $group=ac_filter_records(fn($r)=>$r['family']===$fam || ($fam==='DRAFT' && str_contains($r['timeline_moment_id_or_gen'],'DRAFT'))); if(!$group) continue; ?><section class="panel"><h2><?= ac_e($fam) ?> family</h2><?php ac_record_table($group,true); ?></section><?php endforeach; ?>